import{_ as t,H as i,f as a,i as l}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"21 | 高效管理，让工作事半功倍","description":"","frontmatter":{},"headers":[{"level":2,"title":"学会分类管理","slug":"学会分类管理","link":"#学会分类管理","children":[{"level":3,"title":"成员分类与管理办法","slug":"成员分类与管理办法","link":"#成员分类与管理办法","children":[]},{"level":3,"title":"投入精力的差异化","slug":"投入精力的差异化","link":"#投入精力的差异化","children":[]},{"level":3,"title":"管理方式的差异化","slug":"管理方式的差异化","link":"#管理方式的差异化","children":[]},{"level":3,"title":"管理事情的方法","slug":"管理事情的方法","link":"#管理事情的方法","children":[]},{"level":3,"title":"做提前量","slug":"做提前量","link":"#做提前量","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"技术领导力实战笔记2022/21｜高效管理，让工作事半功倍.md","filePath":"技术领导力实战笔记2022/21｜高效管理，让工作事半功倍.md","lastUpdated":1795558086000}'),n={name:"技术领导力实战笔记2022/21｜高效管理，让工作事半功倍.md"};function p(s,e,E,r,o,h){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_21-高效管理-让工作事半功倍" tabindex="-1">21 | 高效管理，让工作事半功倍 <a class="header-anchor" href="#_21-高效管理-让工作事半功倍" aria-label="Permalink to &quot;21 | 高效管理，让工作事半功倍&quot;">​</a></h1><p>你好，我是邱良军。</p><p>在做技术管理的这些年，我发现团队越大管理工作越多且越复杂。为了更高效地做好管理工作，我摸索出了一些管理方法来提高效率。比如分类管理，把所有的人和事按次序“码放”处理；做提前量，为自己留有余地等等。下面我们就一一看下如何把这些方法应用到我们实际的管理工作中。</p><h2 id="学会分类管理" tabindex="-1">学会分类管理 <a class="header-anchor" href="#学会分类管理" aria-label="Permalink to &quot;学会分类管理&quot;">​</a></h2><p>我们需要把团队里的人和事情做一些分类，并加以区别管理，这个是高效管理的前提。</p><h3 id="成员分类与管理办法" tabindex="-1">成员分类与管理办法 <a class="header-anchor" href="#成员分类与管理办法" aria-label="Permalink to &quot;成员分类与管理办法&quot;">​</a></h3><p>团队成员分为四类：核心骨干（人才）、普通员工、“特殊”员工（问题员工），以及新员工。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/21/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/21/1.png" alt=""></a></p><p>管人要“差异化”，差异化不是不公平，做好了反而能够体现公平公正。差异化不仅表现在我们平时投入的精力上，还表现在对不同类型员工的管理办法上。</p><h3 id="投入精力的差异化" tabindex="-1">投入精力的差异化 <a class="header-anchor" href="#投入精力的差异化" aria-label="Permalink to &quot;投入精力的差异化&quot;">​</a></h3><p>在管理这四类团队员工时，我耗费的精力也不相同。</p><ul><li><p>新员工，平均占我 15% 的精力（和离职率相关，参考 10% 的离职率）；在团队扩张或者组建新团队时，花费精力比较多，要占 50%，新员工管理的好坏直接影响后面的团队管理。</p></li><li><p>问题员工，平均占 2%。在接手新团队和团队扩展时，花费精力比较多，占 30%。</p></li><li><p>普通员工，团队进入平稳成熟阶段，平均占 8%。</p></li><li><p>优秀员工，团队进入平稳成熟阶段，平均占 5%。</p></li></ul><p>从以上分析看，在团队建设的不同阶段，管理团队花费的时间差异很大，新团队组建阶段几乎占了 100%，而一旦成熟后，花费的时间大概 30%。需要强调一下，这个时间分配的前提是：招聘和新员工阶段投入的时间足够多，可以预防问题员工的出现，或者把他消除在萌芽阶段。</p><h3 id="管理方式的差异化" tabindex="-1">管理方式的差异化 <a class="header-anchor" href="#管理方式的差异化" aria-label="Permalink to &quot;管理方式的差异化&quot;">​</a></h3><p>其次，需要用差异化的管理方式来管理这四类员工，有四个关键字：“管理”“处理”“激励”“服务”，具体如下：</p><ol><li>管理好新员工</li></ol><p>这个是管理工作的头等大事，一方面尽量提升新员工的满意度，激发新员工的潜力，为新员工的第一天入职做好充足准备：高调介绍新员工给所有人，指定一名靠谱导师，一起吃饭拉近彼此的距离。紧接着，明确试用期目标：为其制定详细的目标任务分解，细化到第一周、第一个月、第一个季度试用期阶段需要达成的目标，并且定期检查和反馈，留与不留一定要在试用期结束前做出决定。</p><p>新员工试用期阶段是培养员工的关键期，好习惯和坏习惯通常都是在这个时候养成的。这里我想到了孙武练兵，试用期的严苛管理会给后续的团队管理工作减轻很多负担。在此期间，需要观察新员工，根据他的表现把他分为优秀员工、普通员工，甚至问题员工。</p><ol start="2"><li>处理好问题员工</li></ol><p>我们必须客观分析并识别出是哪一种类型，这里可以借鉴京东对问题人员的定义及处理方式。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/21/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/21/2.png" alt=""></a></p><p>对于问题员工要果断地处理，你要记住：不要试图去改变一个人，从根本上去改变一个人是很难做到的。</p><ol start="3"><li>激励好普通员工</li></ol><p>一个团队一定会有能力一般的员工，这个是现实、也是规律，作为管理者要时刻鼓励大家向标杆学习，依靠流程制度来管理。日常管理中，向团队多问问题，抛出有挑战性的问题，不要急于给出结果，让团队自己找答案，技术团队的特点是喜欢接受挑战，作为技术团队的Leader，发现问题、提出问题要比解决问题更重要。</p><ol start="4"><li>最后服务好优秀员工</li></ol><p>先说一下我心目中优秀员工的特点：</p><ul><li><p>对自己工作有干劲、有热情，总是积极主动，是天然的自燃性人才。</p></li><li><p>总是能够尽快完成安排的任务，并思考是否有遗漏或者不完善的地方，有能力及责任心。</p></li><li><p>有好奇心，能够主动学习。</p></li><li><p>热心帮助别人，乐于分享。</p></li></ul><p>优秀员工是公司最核心的资产，通常公司里 80% 的价值是他们创造的，并且他们也是整个公司其他员工学习的榜样，必须把他们树为标杆，也要及时奖励他们的付出。作为管理者，我们的首要任务就是利用一切条件服务好他们，给他们创造好的工作环境，充分信任他们，从内心激发他们的潜能。正如 GE 杰克韦尔奇说过的，“失去最优秀的前 20% 人才，是领导者的失败，留住最差的 10% 也是一种过错”。</p><p>识别出不同员工，做好以上几点，不论团队规模多大，你就基本掌握了团队人员管理的秘诀，并且不会随着团队的扩大而手忙脚乱。同时，我们也要培养能够带团队的管理者，授权给他们，让优秀的员工，特别是有管理能力的优秀员工去帮助你带团队，让团队发生裂变，你自己的认知也将随着团队的发展而提升，你就能轻松应对团队的迅速发展。在此过程中不断学习、思考，你一定会成为一名优秀的领导者。</p><p>选对人，选择合适的方法去管人，打造不需要管理的自驱团队，管理就会变得高效。</p><ul><li>重视并提升招聘能力也会大大降低团队的管理难度，我在上一季的分享中专门用《如何有效地找到你心仪的人才》和《打造高效技术团队的人才招聘攻略》两节介绍过，你可以参考一下。</li></ul><h3 id="管理事情的方法" tabindex="-1">管理事情的方法 <a class="header-anchor" href="#管理事情的方法" aria-label="Permalink to &quot;管理事情的方法&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/21/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/21/3.png" alt=""></a></p><p>管人要做到差异化，而管事则需要做到“标准化”。</p><p>标准化中要尽量做到流程化和定量化，让数字来说话。关键是要控制好每件事的阶段、节点和方法，做到有据可查、可追溯。传统的方式就增加检查点和审批点，工作量巨大，如果没有工具的帮助很难落地。这里我们说的工具指的就是系统，尽量做到事事线上化 / 系统化管理，就是近两年的热点话题“数字化”。一些共享协作文档和办公软件，可以协助我们解决一些标准化问题。</p><p>想要高效处理各项事务，除了标准化管理外，还需要将事情分类管理。</p><p>首先，我们可以使用 WBS 方法分解事项，然后把事情交给专业且适合的人做。</p><ul><li><p>工作分解结构（WBS）是把一个项目分解成任务，任务再分解成一项项工作，再把一项项工作分配到每个人的日常活动中，直到分解不下去为止。</p></li><li><p>参考资料：《13｜工具方法大串讲：手把手教你高效管理》《11 | 项目计划：代码未动，计划先行》</p></li></ul><p>细分过后的各类事项，可以贴上不同的标签，常见的有“重要和紧急”。在此，我增加了一个“复杂”维度，加以利用，可以收到奇效。</p><p>我将这三个维度组合起来产生的情况整理成了一张表格，你可以看一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/21/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/21/4.png" alt=""></a></p><p>前面 1~4 项是重要的事情，必须确保不出问题且按时完成，通常由自己、优秀员工、专业骨干主导来完成。后面 4 项是不重要的事情，在结果可控下，可以利用这些事情来识别、锻炼和培养各类员工，并以此做出合理的工作调整，或者淘汰优化的决定。</p><p>通过这样的安排，既可以稳妥地完成公司的业务目标，还能锻炼和培养团队，一举多得。</p><p>最后，不要让所有的事情都变成紧急的事情，也不要让紧急的事情变得特别紧急以至于处理它的人没有足够的时间应付，过程中产生技术变形。特别是复杂的事情，在保证质量的前提下，需要从容地计划、研究、执行和检查。</p><p>那如何能够避免事情变得更紧急呢？</p><p>解决办法就是在事情不紧急的时候，提前做计划，处理事情有适当的提前量，尤其是复杂的、有难度的事情，这样可以大幅度提升成功率，降低风险。</p><h3 id="做提前量" tabindex="-1">做提前量 <a class="header-anchor" href="#做提前量" aria-label="Permalink to &quot;做提前量&quot;">​</a></h3><p>俗话说“凡事预则立，不预则废”，凡事做提前量，管理事情就会更高效。</p><p>做提前量包括提前准备、提前了解情况、提前开始等等，凡事赶在计划之前，给自己留有余地。在管人上也可以做提前量，比如提前养成新员工的工作习惯、提前识别优秀骨干和问题员工，这样在安排事情指挥团队时，就会游刃有余，从容应对。所以事事做提前量也是高效管理的秘诀之一。</p><p>提前量是一种策略，更是一种做事的态度和习惯，运用得当，处理事情就会从被动变成主动，心态也会发生变化，心里的焦虑和不安会变少，从而行为也会发生改变。所以做提前量是养成好习惯的第一心法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>最后，我们来对今天的内容做一个简单的回顾吧！</p><p>做管理者不难，但做一个称职的管理者很难，这里我分享了一些过去我管理过程中的一点经验。我们需要把人和事划分为不同的类别，像孔子说的“因材施教”，在管理中同样适用，什么样的员工适用于什么样的管理方法，哪个类型的人适合做什么样的事情，管理者要作到心中有数。</p><p>除此之外，我们要做的事情，可以按照重要、紧急和复杂三个维度划分，交给不同的人做不同的事，还可以通过不同事情的安排，既可以达成公司的业务目标，又可识别、锻炼和培养团队成员，做到“鱼和熊掌兼得”。在此基础上，进一步做提前量，管理好任务的进度，不至于因为时间问题导致动作变形，以此来降低管理难度。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/21/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/21/5.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>最后我想给你留两个思考题，你来说一说管理应该是结果导向，还是过程导向？管理应该偏重管事，还是应该偏重管人？欢迎你在评论区分享你的见解，也欢迎你把这节课分享给需要的朋友。</p>',57)])])}const c=t(n,[["render",p]]);export{u as __pageData,c as default};
